  "chunks": [
    {
      "chunk_type": "opening",
      "arabic_text": "وَقَالَ أَمِيرُ الْمُؤْمِنِينَ عَلَيْهِ السَّلَامُ: «مَنْ أَرَادَ أَنْ يَكْتَالَ بِالْمِكْيَالِ الْأَوْفَى فَلْيَكُنْ آخِرُ قَوْلِهِ:",
      "translations": {
        "en": "Amir al-Mu'minin عليه السلام said: “Whoever desires to receive by the fullest measure, then let the last of his speech be:"
      }
    },
    {
      "chunk_type": "quran_quote",
      "arabic_text": "«سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ»",
      "translations": {
        "en": "“Glory be to your Lord, the Lord of Might, above what they describe; and peace be upon the Messengers; and all praise belongs to Allah, the Lord of the worlds.”"
      }
    },
    {
      "chunk_type": "closing",
      "arabic_text": "فَإِنَّ لَهُ مِنْ كُلِّ مُسْلِمٍ حَسَنَةً.",
      "translations": {
        "en": "For indeed, there is for him a good deed from every Muslim.”
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "Imam Ali عليه السلام teaches that ending one’s speech with these Qur'anic words brings immense reward measured in the fullest way. The narration highlights the virtue of dhikr, praising Allah, and invoking peace upon the Messengers through a concluding formula drawn from the Qur'an.",
      "seo_question": "What should a believer say to receive the fullest measure of reward?",
      "key_terms": {
        "أَمِيرُ الْمُؤْمِنِينَ": "The Commander of the Faithful, a title of Imam Ali ibn Abi Talib عليه السلام.",
        "الْمِكْيَالِ الْأَوْفَى": "The fullest measure, meaning complete and abundant reward.",
        "سُبْحَانَ": "Glorification of Allah, declaring Him far above imperfection.",
        "رَبِّ الْعِزَّةِ": "The Lord of Might, affirming Allah’s majesty and power.",
        "الْمُرْسَلِينَ": "The messengers sent by Allah.",
        "الْحَمْدُ لِلَّهِ": "All praise belongs to Allah.",
        "حَسَنَةً": "A good deed or reward."
      }
    }
  },
